import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone

__author__ = 'Adrian Kubala'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'adrian.1.kubala@nokia.com'


class EnableRndPorts(GenericUnixCommand):
    """EnableRndPorts command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Enable RnD Ports command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param prompt: Expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(EnableRndPorts, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.current_ret["SUCCESS"] = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "/opt/trs/www/html/protected/enableRndPorts.cgi"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_service_status(line)
            except ParsingDone:
                pass
        return super(EnableRndPorts, self).on_new_line(line, is_full_line)
    # <p><h3>R&D Ports Service Enabled Successfully</h3>
    _re_service_status = re.compile(r"R&D Ports Service Enabled (?P<SERVICE_STATUS>\w+)")

    def _parse_service_status(self, line):
        """
        Parse service status in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(EnableRndPorts._re_service_status, line):
            self.current_ret["RESULT"] = self._regex_helper.group(0)

            if self._regex_helper.group("SERVICE_STATUS") == "Successfully":
                self.current_ret["SUCCESS"] = True
            raise ParsingDone


